import pathlib,json,re,hashlib,datetime,ast
R=pathlib.Path.cwd(); now=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat()
op=R/'src/data/i18n/en-overrides.json'; o=json.loads(op.read_text(encoding='utf8')); reviews=json.loads((R/'docs/editorial/news-reviews.json').read_text(encoding='utf8'))
def write(slug,meta,paras,sources,review):
 p=R/f'src/pages/news/{slug}.md'; head=p.read_text(encoding='utf8').split('---')[1];fm={}
 for k,v in re.findall(r'^([A-Za-z]\w*): (.+)$',head,re.M):
  try:fm[k]=ast.literal_eval(v)
  except (ValueError,SyntaxError):fm[k]=v
 for k,(z,e) in meta.items():fm[k]=z;o[z]=e
 fm['sources']=[dict(label=a,url=b) for a,b in sources];fm['updated']=now
 body=[]
 for z,e in paras:o[z]=e;body.append(z)
 method='## 資料與報導方法';o[method[3:]]='Sources and reporting method'
 z='本文於2026年11月10日重新查核並擴寫，保留原發布日期。依公開原始文件與具名來源整理，未進行現場採訪；現行資訊與原報導時序分開說明，未公開的個案結果不作推定。'
 o[z]='Rechecked and substantially expanded on November 10, 2026, with the original publication date retained. This report uses public original documents and identified sources without on-site interviews. Current information is distinguished from the original timeline; unpublished individual outcomes are not inferred.'
 text='---\n'+''.join(k+': '+json.dumps(v,ensure_ascii=False)+'\n' for k,v in fm.items())+'---\n\n'+'\n\n'.join(body)+'\n\n'+method+'\n\n'+z+'\n'
 p.write_text(text,encoding='utf8');review.update(reviewedAt=now,bodySha256=hashlib.sha256(re.split(r'^---\s*$',text,flags=re.M)[2].encode()).hexdigest());reviews[slug]=review
 print(slug,len(re.findall('[\u3400-\u9fff]',''.join(body))))

write('jordan-international-university-unified-admissions-2026',{
'title':('約旦國際招生期限更正：學生送件與校方處理是不同日期','Jordan international admissions correction: application and processing deadlines differ'),
'description':('約旦2026/27第一學期公立申請10月8日、私立10月15日截止；10月22日與29日是處理期限。11月10日更正原稿，並釐清私校可直接申請。','For Jordan’s 2026/27 first semester, public applications closed October 8 and private applications October 15; October 22 and 29 were processing dates. This November 10 correction also clarifies direct applications to private institutions.'),
'imageAlt':('大學畢業典禮示意照片，非約旦招生現場','University graduation photograph used for illustration, not a Jordanian admissions event')},[
('考慮到約旦留學，首先要分清自己送出申請的期限，與大學完成審查的期限。本報10月10日原稿把10月22日籠統寫成招生持續日期，並將公私立大學都描述為必須透過統一平台，兩項說法均不夠準確。11月10日依現行官方公告重新核對後，更正如下；這篇是原有報導的修訂，不是新一輪招生開放通知。','Students considering Jordan need to distinguish their submission deadline from the university’s processing deadline. Our October 10 article incorrectly treated October 22 as a general closing date and suggested that both public and private institutions required the unified platform. This November 10 revision corrects both points against official information. It updates an existing report rather than announcing a new application round.'),
('官方2026／27第一學期公告將公立大學與學院的送件及申請費繳付期限列為10月8日下班前，相關處理及錄取程序則至10月22日，或可用名額填滿為止。也就是說，原稿發布時，公告中的公立送件期限已過，讀者不能把還在處理案件的兩週當成仍可提出新申請的時間。','The official first-semester notice sets October 8, 2026, at the end of business for public-university and college applications and application-fee payment. Processing and admissions conclude on October 22 or when available places fill. The public submission deadline had therefore already passed when our original article appeared; the subsequent processing interval was not an additional application window.'),
('私立大學與學院的公告日期另列為10月15日送件及繳費截止、10月29日處理及錄取截止，同樣受可用名額限制。截至本次11月10日查核，這四個日期均已經過。未取得另行延長或新學期公告前，本文不將舊頁仍可瀏覽、系統仍有入口，解讀為當期招生仍開放，也不替個別學校推定可以補件。','For private institutions, the notice lists October 15 for applications and payment and October 29 for processing and admissions, again subject to vacancies. All four dates had passed by the November 10 recheck. An accessible webpage or system entrance does not establish an extension or a new intake, and this report does not infer late-submission permission for any institution.'),
('申請路徑也須按學校類型區分。官方說明公立機構的國際學生須經統一系統；私立機構則可使用系統，或直接聯繫大學。學生可在系統填列最多十個選項，但選項數量不等於錄取數量。初步、附條件與正式錄取也有不同效力，收到通知時應閱讀尚待履行的要求，而不是只看到錄取字樣就付款。','The official route differs by institution: international applicants to public institutions must use the unified system, while private applicants may use it or contact the university directly. Up to ten choices do not mean ten offers. Preliminary, conditional and final admissions also have different implications; applicants should read outstanding requirements before making payments.'),
('這項更正以Study in Jordan當期公告及科系查詢頁為主要依據，並核對約旦國家通訊社6月1日的開放招生報導。通訊社此篇依主管機關公告整理，不能算成獨立調查的第二份證據。因此另以學歷評估機構World Education Services旗下WENR對約旦高教制度的分析交叉理解背景，不把不同網站刊出相同公告誤稱兩次獨立查核。','The correction relies on the current Study in Jordan notice and program directory, checked against Petra’s June 1 opening report. Petra attributes that report to the ministry, so it is not a second independent investigation. WENR, published by credential evaluator World Education Services, supplies independently compiled system context; duplicated announcements are not presented as independent corroboration.'),
('WENR的制度介紹區分公立大學、私立大學與提供應用或技術資格的學院，也列出學位層級、授課語言與品質保證架構。這些差異提醒申請人，使用同一入口並不代表取得同一種資格，阿拉伯語與英語並存也不表示每個課程都是全英語。該分析不驗證2026年個別截止日，日期仍須回到當期官方文件。','WENR distinguishes public and private universities from colleges offering applied or technical qualifications and describes award levels, instructional languages and quality assurance. A shared application entrance does not make qualifications equivalent, and the coexistence of Arabic and English does not make every course English-taught. This system analysis does not validate individual 2026 deadlines, which remain matters for the dated official notice.'),
('校方實際文件要求可從另一所機構的原始說明看出細節。Zarqa University的國際學生專頁指出，持外國高中資格者在需要辦理同等學歷認定時，涉及校方致主管機關函件；轉學生與已持學位者另須確認原就讀機構的認可情形。這是該校程序的例子，不能直接套用所有學校，卻說明上傳成績單並非整個學歷審查的終點。','Zarqa University’s international admissions page illustrates institutional implementation. Where secondary-school equivalency is required for a foreign credential, it describes a university letter to the relevant ministry; transfer and degree-holding applicants also face recognition checks on prior institutions. These are that university’s procedures, not universal instructions, but they show why uploading a transcript may not complete credential assessment.'),
('對台灣家庭而言，選校前宜把課程名稱、實際授課語言、學位頒授機構與畢業要求放在同一份比較表，再向學校確認證明文件與翻譯格式。若目標涉及醫療或其他專業執業，還須另外查明未來工作地的資格要求。這是從跨制度申請差異提出的規劃建議，不是本文已確認某一約旦學位必然能在台灣取得專業資格。','Taiwanese families can compare the program title, actual teaching language, awarding institution and graduation requirements together, then confirm documentation and translation formats. Those aiming at medicine or another regulated profession should separately establish requirements in the intended place of practice. This is a planning implication of cross-system study, not a finding that a particular Jordanian degree automatically confers professional eligibility in Taiwan.'),
('預算也不宜只看入口顯示的單一費用。科系查詢、申請服務、學費、住宿與日常生活各有不同計價基礎；本次未核實個人完整帳單，因此不提供一個看似精確的總額。若透過第三方協助，應要求列明服務與官方費用，並自行保存學校往來紀錄。這樣才能分辨大學正式條件與代辦的說明，降低資訊轉述造成的誤會。','Budgeting should separate application services, tuition, accommodation and living costs rather than relying on one figure displayed at an entrance page. No complete individual bill was verified for this report, so no purported total is supplied. Anyone using an intermediary can request an itemized distinction between service charges and institutional fees and retain direct university correspondence to distinguish official conditions from third-party explanations.'),
('後續報導應追蹤新的學期公告、科系空缺與資格認定程序是否更新，並保持事件日期、申請期限與查核日期清楚分開。本文保留10月10日發布紀錄，公開指出原標題及內文錯誤；不把11月查到的更正悄悄寫成原先就已正確。讀者目前應先查下一個明確開放的申請批次，而非依據原稿的10月22日採取送件行動。','Future coverage should track new intake notices, vacancies and credential procedures while distinguishing event dates, deadlines and verification dates. We retain the October 10 publication record and explicitly correct the original headline and text rather than silently backdating the correction. Readers should now identify a clearly open future intake instead of acting on the original October 22 wording.')],
[('Study in Jordan — current 2026/27 notice','https://studyinjordan.jo/Announcement1En.aspx'),('Study in Jordan — dated program directory notice','https://studyinjordan.jo/MajorsSearchEn.aspx'),('Petra — June 1 ministry announcement, not independent investigation','https://org.petra.gov.jo/Include/InnerPage.jsp?ID=85162&lang=en&name=en_news'),('WENR / WES — independent education-system analysis','https://wenr.wes.org/country-profiles/higher-education-sections/jordan-higher-education/'),('Zarqa University — institutional implementation','https://www.zu.edu.jo/en/admissionandregisteration/InternationalStudents.aspx?dean=1&id=1&page=21')],dict(newsValue='公開更正原稿把處理截止當申請截止的實質錯誤，避免台灣家庭依已過期日期送件。',background='區分約旦公私立申請路徑與學位制度，以WENR分析補充制度背景及品質認證差異。',development='保留十月十日原始日期，十一月十日明示更正，四個當期截止均已過不再宣稱開放。',perspectives='主管機關提供當期日期，WENR提供獨立制度背景，Zarqa提供校方實務而非虛構訪談。',taiwanImpact='提醒台灣家庭分清資格認定、授課語言、學費與未來執業需求，不保證個人學位採認。',uncertainty='未查得延長或新批次就不推定仍開放，保留個別補件、帳單及專業資格的未知界線。',independence='WENR是WES的獨立制度分析，非六月招生公告轉載；Petra依公告報導的限制明確揭露。',primarySource='https://studyinjordan.jo/MajorsSearchEn.aspx',independentSource='https://wenr.wes.org/country-profiles/higher-education-sections/jordan-higher-education/'))

write('nagoya-g30-undergraduate-2027-application',{
'title':('名古屋大學2027英語本科首輪申請中：11月19日截止，先核對課程與文件','Nagoya’s 2027 English-taught undergraduate first round closes November 19: check course and document requirements'),
'description':('名古屋G30首輪2026年11月19日日本中午截止，台北為上午11時。補充標準化測驗屬建議、英語豁免條件與不同頁面差異，避免只憑英文成績選校。','Nagoya G30’s first round closes at noon in Japan on November 19, 2026, or 11 a.m. in Taipei. This revision clarifies recommended tests, English waivers and differences between university webpages.'),
'imageAlt':('教室學習示意照片，非名古屋大學招生現場','Classroom photograph used for illustration, not a Nagoya University admissions event')},[
('想在日本以英語完成大學學位，申請時仍要同時看課程適合度與學術證據。名古屋大學Global 30（G30）2027年入學的英語本科首輪已於11月2日開放，11月19日日本時間中午截止，換算台北時間是上午11時。這次11月10日更新保留原報導日期，把原先的預告改為當下進行中的申請資訊，並補正測驗要求的表述。','An English-taught degree in Japan still requires attention to course fit and academic evidence. Nagoya University’s first G30 undergraduate round for 2027 entry opened November 2 and closes at noon Japan time on November 19, or 11 a.m. in Taipei. This November 10 update retains the original publication date, replaces the earlier preview with current application information and clarifies testing requirements.'),
('校方另列第二輪於2027年1月5日上午9時開放、1月21日中午截止，時間均採日本時區。兩輪的結果公布日分別為3月15日與4月26日。這些是申請與結果時程，不能理解為所有科系都有同樣剩餘名額；學生應先閱讀當年課程清單與各輪規定，再安排台灣升學考試及其他海外申請，避免把不同時區的中午當成台北中午。','The second round runs from 9 a.m. on January 5 to noon on January 21, 2027, in Japan time. Final decisions are scheduled for March 15 and April 26 respectively. These dates do not establish equal availability across courses. Applicants should check the current program and round rules when coordinating Taiwanese examinations and other overseas applications, taking care over the one-hour time difference.'),
('G30是校內英語授課學位管道，不等於名古屋大學所有本科都改用英語招生。校方一般大學部介紹分開列出日語課程與十月入學的英語課程；G30也提供日語學習安排。對學生而言，選擇這條管道是選擇特定科系的教學設計，而不是先選一所大學，再假設校內任何想修的專業都能以相同方式申請。','G30 is a university pathway for English-taught degrees, not a conversion of all Nagoya undergraduate admissions into English. The general undergraduate overview distinguishes Japanese-taught provision from English programs entering in October, and G30 includes Japanese-language learning. Applicants are choosing particular programs and teaching arrangements, not gaining the same application route to every subject at the university.'),
('原稿把標準化測驗資料寫得像一律必交，容易讓學生誤判。現行G30招生頁說明標準化測驗並非普遍強制，但建議提交，以利呈現學術能力；個別教育制度、資格與科系仍須依當期清單核對。沒有一項通用強制測驗，並不表示沒有學術要求；同樣地，已考SAT、ACT或其他測驗，也不會取代高中成績、課程背景與文件審查。','The original wording could imply that standardized tests were universally compulsory. The current G30 page says they are not generally mandatory but recommends submitting them to demonstrate academic ability; curriculum-specific credentials and program checklists still matter. The absence of one universal test requirement does not remove academic requirements, and a test score does not replace school records, subject preparation or document assessment.'),
('英語能力豁免須特別注意頁面層級。G30招生專頁目前列出連續三年中學教育、包含最後一年以英語授課等條件，並要求校方簽署蓋章的證明；大學另一本一般語言說明頁則使用四年的表述。本次不把兩者混成同一規則，也不自行認定每位雙語學校學生都能豁免。申請人應依2027年度G30要求備件，遇疑義向招生單位取得確認。','Page scope matters for English waivers. The G30 admissions page describes three consecutive years of secondary education including the final year in English, supported by a signed and stamped school statement. A general university language page uses four years. This report records the difference rather than merging the rules or declaring every bilingual-school student exempt. Applicants should use the 2027 G30 requirements and seek clarification where their circumstances are uncertain.'),
('獨立於名古屋大學的Cambridge International日本升學指南，將該校列為接受劍橋資格的日本院校之一，並提醒不同科系會有不同科目要求，英語與日語課程也有不同準備方式。這個來源有推廣自身資格的立場，本文予以揭露；它可交叉檢視申請制度，不能用來驗證名古屋2027年的每個日期，更不能保證持有某種資格就會被錄取。','Cambridge International’s Japan guide, produced separately from Nagoya, lists the university among institutions accepting Cambridge qualifications and emphasizes course-specific subjects and different preparation for English and Japanese routes. Cambridge has an interest in promoting its qualifications, which should be disclosed. Its guide supplies an independent institutional perspective on pathways, not confirmation of every Nagoya 2027 date or a guarantee of admission.'),
('文件準備應回到學生實際接受的課程制度。學校成績、畢業或預計畢業證明、語言資料、推薦及申請文章各有用途；非英語文件的原件與認證翻譯，也不能因為系統接受上傳就省略核對。本文不替未見到的個人文件判定合格，建議學生把當期清單逐項對照，讓推薦教師與學校行政有足夠時間準備，並保留上傳完成紀錄。','Documentation should match the applicant’s actual curriculum. Transcripts, graduation or expected-graduation evidence, language records, references and essays serve different purposes. Originals and certified translations of non-English documents still require attention even where the system accepts uploads. This report cannot assess unseen personal documents; a checklist shared early with teachers and school administrators helps avoid last-minute omissions and preserves submission records.'),
('書面審查後的面試，是了解學生能否進入課程學習的另一環節，不能只準備一篇背熟的自我介紹。從選科的角度，學生宜能說清楚自己在高中學過哪些相關內容、遇到什麼學術問題，以及為何課程設計適合後續目標。這是依文件加面試制度提出的準備建議，不是校方公布的評分祕訣，也沒有保證照著回答就能提高多少錄取率。','An interview following document screening is another opportunity to assess readiness, rather than simply recite a prepared introduction. Students can prepare to explain relevant schoolwork, academic questions and the connection between the course and their goals. This follows from the document-and-interview structure; it is not an unpublished scoring formula or a claim that particular answers produce a quantified admissions advantage.'),
('日本學生支援機構的英語學位資訊也提醒，即使學位以英語完成，日語能力仍有助於日常生活及未來工作。對台灣學生，這代表預算與時間表應同時包含語言學習、生活適應及學業安排，而不是把免日語入學理解成在日本四年都不需要日語。是否適合留下工作，還涉及個人能力、職缺與其他條件，本文不提供就業保證。','JASSO’s information on English-taught degrees also notes the usefulness of Japanese for daily life and future employment. Taiwanese students can therefore plan language learning and adaptation alongside academic study rather than treating an English entry route as evidence that Japanese will never matter. Employment prospects also depend on personal skills, vacancies and other conditions; no employment guarantee follows from the degree pathway.'),
('這次更新的重點，是讓家庭能分開判斷「趕得上哪一輪」、「是否符合申請條件」與「課程是否值得投入」。截止日前應確認時區、完整文件與官方清單，錄取後再按正式通知規劃入學費用及住宿。後續若校方調整輪次、文件或豁免文字，仍須追蹤最新版本；目前沒有公開個案資料足以推定台灣申請人的錄取難易或成功比例。','The practical purpose of this update is to separate timing, eligibility and course value. Before the deadline, families should confirm the time zone, complete documents and official checklist; after an offer, costs and housing should follow formal instructions. Changes to rounds, documents or waiver wording require continued monitoring. No published applicant-level evidence reviewed here establishes an admissions rate or difficulty level specifically for Taiwanese applicants.')],
[('Nagoya G30 — current undergraduate admissions','https://admissions.g30.nagoya-u.ac.jp/admissions/undergraduate/'),('Nagoya — undergraduate routes','https://en.nagoya-u.ac.jp/admissions/undergraduate/'),('Nagoya — general language page with different waiver wording','https://en.nagoya-u.ac.jp/admissions/japan/language/'),('Cambridge International — independent qualification-provider guidance','https://www.cambridgeinternational.org/programmes-and-qualifications/recognition-and-acceptance/country/japan/applying-to-universities/'),('JASSO — degree and language planning','https://www.studyinjapan.go.jp/en/planning/learn-about-schools/universities/')],dict(newsValue='將首輪預告更新為進行中的申請，補正測驗非全面強制與日本台北時差，避免實際送件失誤。',background='交代G30特定英語本科與一般日語本科路徑差異，不把校名等同全校課程都可英語申請。',development='保留原始十月發布時間，十一月重新核實兩輪日期、文件與英語豁免頁面文字差異。',perspectives='校方招生頁配合Cambridge獨立資格指南及JASSO生活語言觀點，未捏造面試或學生經驗。',taiwanImpact='具體換算台北十一時截止並提出學校文件協作與選課問題，不承諾台灣學生錄取率。',uncertainty='披露三年與四年英語豁免文字差異、個別科系限制與未知錄取率，不自行替個案裁定資格。',independence='Cambridge為校外資格提供者的原始指南，揭露推廣自身資格立場，不把指南當2027日期證據。',primarySource='https://admissions.g30.nagoya-u.ac.jp/admissions/undergraduate/',independentSource='https://www.cambridgeinternational.org/programmes-and-qualifications/recognition-and-acceptance/country/japan/applying-to-universities/'))

write('eduhk-2027-international-undergraduate-admissions',{
'title':('香港教育大學2027本科早輪11月16日截止：台灣學生先核對資格與文件','EdUHK’s 2027 undergraduate early round closes November 16: Taiwanese applicants should check qualifications and documents'),
'imageAlt':('香港理工大學校園照片，僅作香港高教背景示意，非香港教育大學','Hong Kong Polytechnic University campus, illustrating Hong Kong higher education rather than EdUHK')},[
('正在比較香港本科課程的台灣學生，除了看申請截止日，也要確認自己使用哪一種學歷資格與申請身分。香港教育大學2027／28國際資格本科申請於10月5日開放，早輪將於2026年11月16日截止。本文11月10日重新核對時，距早輪截止仍有時間，但早送件不代表保證錄取；完整文件與課程適合度仍是規劃核心。','Taiwanese students comparing Hong Kong degrees need to identify their qualification and application status as well as the deadline. EdUHK’s international-qualifications undergraduate applications for 2027/28 opened October 5, with the early round closing November 16, 2026. At this November 10 recheck that deadline remained ahead, but earlier submission does not guarantee admission; complete documentation and course suitability remain central.'),
('校方日期頁另列主輪2027年1月6日、晚輪5月7日，並說明時程可能調整。審查採滾動方式，申請人可在未取得最終成績時先申請，再依要求更新；但缺少必要文件的案件不會進入面試考慮。這兩點應一起理解：可後補尚未公布的考試結果，不代表可以忽略系統已要求提供的其他證明。','The dates page lists January 6, 2027, for the main round and May 7 for the late round, subject to revision. Rolling assessment allows applicants awaiting final examination results to apply and update them later, but cases missing required documents are not considered for interview. Permission to supply future results later does not remove the obligation to provide other required evidence.'),
('台灣學歷條目目前列出學測英語達頂標、包含國文在內另外三科達均標的組合，並另有其他資格路徑。這是公開的入門條件說明，不是實際錄取分數或最低分保證。頁面仍保留舊制指考名稱，因此採用不同年度或新制考試的學生，應向招生單位確認對應方式，不宜自行把舊欄位直接換成另一種測驗。','The Taiwan qualification entry currently describes GSAT English at the top benchmark and three other subjects, including Chinese, at the average benchmark, alongside other qualification routes. These are published entry conditions rather than observed admission scores or a guarantee. The page also retains an older AST examination reference; applicants using a different or newer examination should seek confirmation rather than assume equivalence.'),
('英語要求與學歷門檻亦應分開閱讀。校方資格頁提供台灣考試英語成績及一般英語條件的連結，個別課程也可能另有要求。曾在英語環境讀書、持有國際課程資格或達到某一成績，均不應被新聞摘要直接判成所有條件已滿足。家庭可先整理現有證明與待取得成績，讓招生單位針對明確問題回覆，減少來回補件。','English evidence and academic entry conditions should be read separately. The qualification page identifies Taiwanese examination English results and links to general requirements, while individual programs may impose additional conditions. English-medium schooling or an international credential should not be treated by a news summary as automatic satisfaction of every rule. A clear inventory of available and pending evidence can make questions to admissions more precise.'),
('申請身分也不只取決於居住地。校方另有非本地學生身分說明，學生應按自身證件與適用資格選擇管道，而不是因為人在台灣，就假設一定只有同一種表格與費率。本文未查閱任何個人證件，不替個案判定身分。課程是政府資助還是自資、學位名稱及年期，也應先釐清，才能做有意義的學費與生活預算比較。','Application status is not determined solely by residence. EdUHK separately explains non-local status, so students should choose the route appropriate to their documents and qualifications instead of assuming that everyone living in Taiwan uses one form or fee category. No personal documents were reviewed here. Funding mode, degree title and duration also need clarification before tuition and living-cost comparisons become meaningful.'),
('這一輪招生置於香港擴大非本地學生容量的背景下。香港電台2月14日報導教育局長蔡若蓮的電台訪問，提到2026／27起相關非本地名額上限提高至本地學額的50%。這個百分比以本地學額為基準，不是說每所大學的一半學生都必須來自境外，也不能把制度上限當成香港教育大學對每個課程的實際招生配額。','The intake sits within Hong Kong’s expansion of non-local capacity. RTHK’s February 14 report of a radio interview with Education Secretary Christine Choi described the relevant cap rising to 50 percent of local places from 2026/27. The denominator is local places: this does not require half of all students to be non-local, nor does the system ceiling establish EdUHK’s actual allocation for each program.'),
('該訪問亦談到學生宿舍供應與未來新增宿位，反映招生擴張必須搭配生活設施。對家庭的實際意義，是錄取與住宿應各自取得明確資訊；全港規劃新增床位，不能換算成某位新生已獲宿舍。這是由政策與生活安排之間的關係提出的提醒，並非本報取得教大當期宿位不足的個案證據，也不以全港消息推定單校服務品質。','The interview also addressed accommodation capacity and future hostel provision, illustrating the link between recruitment and living infrastructure. For families, an academic offer and accommodation confirmation remain separate matters. Territory-wide planned beds do not establish an individual student’s allocation. This is a planning implication, not evidence of a current EdUHK housing shortfall or a judgment about its services.'),
('校方目前把面試與結果安排在2026年12月至2027年5月的區間，後續宿舍及迎新事項則有另外時程。申請人應監看系統及正式電郵，閱讀附條件錄取的每一項要求。若同時持有其他學校選項，可比較確認名額、繳費及補交文件的時間，而不是只用哪所學校最早回覆判斷哪個選擇最好。','The university schedules interviews and offers across December 2026–May 2027, with separate accommodation and orientation stages. Applicants should monitor the system and official email and read each condition attached to an offer. When comparing several institutions, confirmation, payment and document deadlines are more informative than simply treating the earliest response as the best choice.'),
('對希望修讀教育相關領域的學生，還應分清學術學位、實習安排與未來任教資格三件事。課程介紹中的教育主題，不能自行推論為畢業後可在任何地區任教；是否需要額外訓練或認證，應按目標工作地查詢。這是選課時值得向院系提出的問題，本文沒有查得足以保證台灣個別教師資格的證據，也不替專業審查機關作決定。','Students interested in education should distinguish an academic award, practical placements and future teaching eligibility. An education-related course description does not establish permission to teach in every jurisdiction; additional training or recognition depends on the intended workplace. This is a useful question for the department, not a confirmed entitlement to a Taiwanese teaching qualification or a substitute for the relevant authority’s assessment.'),
('本次修訂以教大日期、資格與身分專頁作原始依據，另使用香港電台對政策人物的原始訪問作獨立背景，不把校際截止日彙整網站當成第二份招生規則。報導保留10月10日發布日期，清楚區分11月重新查核內容。配圖為香港理工大學校園，只用來呈現香港高教環境，並非教大校園或本次招生活動現場，避免讀者因圖片誤認學校。','This revision uses EdUHK’s dates, qualification and status pages as primary sources and RTHK’s original interview coverage as independent context, rather than treating a deadline aggregator as a second set of admission rules. It preserves the October 10 publication date and identifies the November recheck. The photograph shows Hong Kong Polytechnic University as general higher education context, not EdUHK or this admissions process.')],
[('EdUHK — current international qualification dates','https://www.apply.eduhk.hk/ug/nonlocal_dates'),('EdUHK — international entrance qualifications','https://www.apply.eduhk.hk/ug/nonlocal'),('EdUHK — non-local status and institutional information','https://www.eduhk.hk/acadprog/nonlocal/'),('RTHK — original February 14 radio interview reporting','https://news.rthk.hk/rthk/en/component/k2/1843827-20260214.htm'),('Hong Kong Education Bureau — local-place denominator, page 287','https://www.edb.gov.hk/attachment/en/about-edb/press/legco/replies-to-fc/edb-e-2627.pdf')],dict(newsValue='補入台灣學測資格、舊制考試文字與文件完整要求，讓早輪截止資訊可直接支援選校準備。',background='將教大2027招生放進香港非本地容量政策背景，清楚解釋百分比母數而非推定單校人數。',development='保留十月發布日，十一月核對早輪仍開放、主晚輪與面試時程，不把未來宿舍計畫當現況。',perspectives='教大原始規則加上香港電台原始訪問，分開校方招生與政策住宿觀點，不虛構受訪學生。',taiwanImpact='提醒台灣申請人逐項核對學測、身分、英語、課程與未來職涯資格，不能以居住地概括管道。',uncertainty='揭露頁面保留舊制指考名稱，未知個人資格與宿位不代判，名額上限不等於實際錄取數。',independence='香港電台對教育局長的原始電台訪問與教大招生文件分開產生，非截止日網站轉載公告。',primarySource='https://www.apply.eduhk.hk/ug/nonlocal_dates',independentSource='https://news.rthk.hk/rthk/en/component/k2/1843827-20260214.htm'))
